/**
 * Block Puzzle piece library (pure data, UI independent).
 *
 * Pieces never rotate during play: every orientation is a separate shape with its own id.
 * Orientations are generated by rotating a base pattern by 90° and removing duplicates, so a
 * family such as the S piece only yields its two distinct orientations.
 */
export type ShapeFamily =
  | 'mono'
  | 'line2'
  | 'line3'
  | 'line4'
  | 'line5'
  | 'square2'
  | 'square3'
  | 'corner3'
  | 'l4'
  | 'j4'
  | 't4'
  | 's4'
  | 'z4'
  | 'corner5';

/** [row, col] offset from the top-left corner of the bounding box. */
export type Offset = readonly [number, number];

export interface Shape {
  id: string;
  family: ShapeFamily;
  /** Normalised cells (top-left of the bounding box is 0,0), sorted by row then column. */
  cells: readonly Offset[];
  /** Bounding box width (columns) and height (rows). */
  w: number;
  h: number;
  /** Palette colour index, 1..PALETTE_SIZE (0 is reserved for empty board cells). */
  color: number;
  /** Base generation weight of this orientation. */
  weight: number;
  /** Big pieces (5+ blocks) become rarer when the board is crowded. */
  big: boolean;
}

export const PALETTE_SIZE = 8;
export const BIG_PIECE_CELLS = 5;

interface FamilyDef {
  family: ShapeFamily;
  base: readonly Offset[];
  color: number;
  /** Total weight of the family, split evenly between its orientations. */
  weight: number;
}

const FAMILIES: readonly FamilyDef[] = [
  { family: 'mono', base: [[0, 0]], color: 4, weight: 4 },
  { family: 'line2', base: [[0, 0], [0, 1]], color: 2, weight: 7 },
  { family: 'line3', base: [[0, 0], [0, 1], [0, 2]], color: 3, weight: 8 },
  { family: 'line4', base: [[0, 0], [0, 1], [0, 2], [0, 3]], color: 1, weight: 6 },
  { family: 'line5', base: [[0, 0], [0, 1], [0, 2], [0, 3], [0, 4]], color: 7, weight: 4 },
  { family: 'square2', base: [[0, 0], [0, 1], [1, 0], [1, 1]], color: 6, weight: 7 },
  {
    family: 'square3',
    base: [[0, 0], [0, 1], [0, 2], [1, 0], [1, 1], [1, 2], [2, 0], [2, 1], [2, 2]],
    color: 5,
    weight: 3,
  },
  { family: 'corner3', base: [[0, 0], [1, 0], [1, 1]], color: 8, weight: 8 },
  { family: 'l4', base: [[0, 0], [1, 0], [2, 0], [2, 1]], color: 5, weight: 5 },
  { family: 'j4', base: [[0, 1], [1, 1], [2, 1], [2, 0]], color: 1, weight: 5 },
  { family: 't4', base: [[0, 0], [0, 1], [0, 2], [1, 1]], color: 7, weight: 6 },
  { family: 's4', base: [[0, 1], [0, 2], [1, 0], [1, 1]], color: 3, weight: 3 },
  { family: 'z4', base: [[0, 0], [0, 1], [1, 1], [1, 2]], color: 6, weight: 3 },
  { family: 'corner5', base: [[0, 0], [1, 0], [2, 0], [2, 1], [2, 2]], color: 2, weight: 5 },
];

/** Moves the cells so the bounding box starts at 0,0 and sorts them (row-major). */
export function normalize(cells: readonly Offset[]): Offset[] {
  const minR = Math.min(...cells.map((c) => c[0]));
  const minC = Math.min(...cells.map((c) => c[1]));
  return cells.map(([r, c]) => [r - minR, c - minC] as const).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
}

/** Rotates 90° clockwise and normalises. */
export function rotate(cells: readonly Offset[]): Offset[] {
  return normalize(cells.map(([r, c]) => [c, -r] as const));
}

export const cellsKey = (cells: readonly Offset[]) => cells.map(([r, c]) => `${r}.${c}`).join('|');

/** Distinct orientations of a pattern, in rotation order starting with the base. */
export function orientations(base: readonly Offset[]): Offset[][] {
  const out: Offset[][] = [];
  const seen = new Set<string>();
  let current = normalize(base);
  for (let i = 0; i < 4; i++) {
    const key = cellsKey(current);
    if (!seen.has(key)) {
      seen.add(key);
      out.push(current);
    }
    current = rotate(current);
  }
  return out;
}

function build(): Shape[] {
  const shapes: Shape[] = [];
  for (const def of FAMILIES) {
    const variants = orientations(def.base);
    variants.forEach((cells, i) => {
      shapes.push({
        id: `${def.family}-${i}`,
        family: def.family,
        cells,
        w: Math.max(...cells.map((c) => c[1])) + 1,
        h: Math.max(...cells.map((c) => c[0])) + 1,
        color: def.color,
        weight: def.weight / variants.length,
        big: cells.length >= BIG_PIECE_CELLS,
      });
    });
  }
  return shapes;
}

export const SHAPES: readonly Shape[] = build();
export const SHAPE_IDS: readonly string[] = SHAPES.map((s) => s.id);

const BY_ID = new Map(SHAPES.map((s) => [s.id, s]));

export function isShapeId(id: string): boolean {
  return BY_ID.has(id);
}

/** Looks up a shape by id. Ids come from validated state, so an unknown id is a programming error. */
export function shapeOf(id: string): Shape {
  const shape = BY_ID.get(id);
  if (!shape) throw new Error(`Unknown block puzzle shape: ${id}`);
  return shape;
}
